{
  "findings": [
    {
      "check_id": "CKV_GCP_37",
      "title": "Compute disk lacks customer-supplied encryption",
      "resource": "google_compute_disk.changeme_count_attached_disk_disk",
      "severity": "MEDIUM",
      "explanation": "The persistent disk has no disk_encryption_key block, so it is not encrypted with a customer-supplied encryption key as required by the applicable policy."
    }
  ],
  "patched_code": "variable "customer_supplied_disk_encryption_key" {
  description = "RFC 4648 base64-encoded 256-bit customer-supplied encryption key for the compute disks."
  type        = string
  sensitive   = true
}

resource "google_compute_disk" "changeme_count_attached_disk_disk" {
  name                      = "changeme-count-attached-disk-disk-${count.index}"
  count                     = var.changeme_google_attached_disk_count_number_of_instances
  type                      = "pd-ssd"
  zone                      = "us-central1-a"
  size                      = 4
  physical_block_size_bytes = 4096

  disk_encryption_key {
    raw_key = var.customer_supplied_disk_encryption_key
  }
}
",
  "fix_summary": "Added a sensitive, required input variable for the customer-supplied encryption key and configured the disk_encryption_key block to use it. No credential or key material is embedded in the Terraform file."
}
